CREATE TABLE IF NOT EXISTS "user_reports" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "reporter_user_id" uuid NOT NULL REFERENCES "users"("id"), "reported_user_id" uuid NOT NULL REFERENCES "users"("id"), "category" varchar(40) NOT NULL, "reason" varchar(1000) NOT NULL, "context_type" varchar(40), "context_id" varchar(255), "context_snapshot" jsonb, "status" varchar(24) NOT NULL DEFAULT 'pending', "reviewed_by_admin_id" uuid REFERENCES "users"("id"), "reviewed_at" timestamp, "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "idx_user_reports_status" ON "user_reports"("status"); CREATE INDEX IF NOT EXISTS "idx_user_reports_reported" ON "user_reports"("reported_user_id"); CREATE INDEX IF NOT EXISTS "idx_user_reports_created" ON "user_reports"("created_at");
CREATE TABLE IF NOT EXISTS "moderation_actions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "report_id" uuid REFERENCES "user_reports"("id") ON DELETE SET NULL, "subject_user_id" uuid NOT NULL REFERENCES "users"("id"), "actor_admin_id" uuid NOT NULL REFERENCES "users"("id"), "action" varchar(24) NOT NULL, "reason" varchar(1000) NOT NULL, "expires_at" timestamp, "created_at" timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "idx_moderation_actions_subject" ON "moderation_actions"("subject_user_id"); CREATE INDEX IF NOT EXISTS "idx_moderation_actions_report" ON "moderation_actions"("report_id");
